}(1)

var wg sync.WaitGroup
for i := 0; i < 3; i++ {
    wg.Add(1)
    go func(id int) {
        defer wg.Done()
        fmt.Printf("Task %d erledigt\n", id)
    }(i)
}
wg.Wait() // Wartet auf alle 3 Worker

