sections.solutionCode:
package main

import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup
    wg.Add(1)

    go func() {
        defer wg.Done()
        fmt.Println("Datenverarbeitung abgeschlossen")
    }()

    wg.Wait()
    fmt.Println("Hauptprogramm beendet")
}
